package local.snapexplorer.mobile;
import android.app.*;import android.content.*;import android.database.Cursor;import android.os.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.zip.*;
/** Imports public MIT fixture records; media bytes are our generated colours. */
public final class PublicFixtureSmoke extends Instrumentation {
 private int checks;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle r=new Bundle();try{run();r.putString("stream","PASS "+checks+" public-fixture Android checks\n");finish(Activity.RESULT_OK,r);}catch(Throwable e){StringWriter w=new StringWriter();e.printStackTrace(new PrintWriter(w));r.putString("stream",w.toString());finish(Activity.RESULT_CANCELED,r);}}
 private void check(boolean ok,String name){if(!ok)throw new AssertionError(name);checks++;}
 private void asset(ZipOutputStream zip,String path,String name)throws Exception{zip.putNextEntry(new ZipEntry(path));try(InputStream in=getContext().getAssets().open(name)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)zip.write(b,0,n);}zip.closeEntry();}
 private long count(ChatRepository repo,String sql){try(Cursor c=repo.getReadableDatabase().rawQuery(sql,null)){c.moveToFirst();return c.getLong(0);}}
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private void run()throws Exception{
  Context c=getTargetContext();List<ChatRepository.Input> inputs=new ArrayList<>();for(int i=0;i<2;i++){File part=new File(c.getCacheDir(),"public-fixture-"+i+".zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(part))){asset(z,"json/chat_history.json",i==0?"chat_history.json":"chat_history-copy.json");if(i==1){asset(z,"chat_media/2024-01-02_b~abc.jpg","sticker.png");asset(z,"chat_media/2024-05-05_b~zzz.png","avatar.png");}}inputs.add(new ChatRepository.Input(part,"Public MIT fixture part "+i,false));}
  ChatRepository repo=new ChatRepository(c);repo.importArchives(inputs,true,(a,b)->{});check(count(repo,"SELECT COUNT(*) FROM messages")==4,"Overlapping public inputs import four distinct events");check(count(repo,"SELECT COUNT(*) FROM messages WHERE body='hey'")==1,"Overlapping hey record imports once");check(count(repo,"SELECT COUNT(*) FROM messages WHERE body='hey' AND own=1")==1,"Sender direction retained");check(count(repo,"SELECT COUNT(*) FROM media")==2,"Linked and unrelated local media retained");check(count(repo,"SELECT COUNT(*) FROM message_media link JOIN messages m ON m.id=link.message_id WHERE m.chat='pal'")==1,"Pipe and tilde media ID links existing local file");check(count(repo,"SELECT COUNT(*) FROM message_media link JOIN messages m ON m.id=link.message_id WHERE m.chat='other'")==0,"Missing sticker cannot borrow unrelated image");check(count(repo,"SELECT COUNT(*) FROM metadata")==2,"Both public source metadata snapshots retained");repo.getWritableDatabase().execSQL("UPDATE messages SET media_refs='[\"b~abc|b~def\"]' WHERE kind='MEDIA'");repo.getWritableDatabase().delete("message_media",null,null);repo.putSetting("export_catalog","old-v2-index");ExportCatalog.ensure(repo,(a,b)->{});check(count(repo,"SELECT COUNT(*) FROM message_media link JOIN messages m ON m.id=link.message_id WHERE m.chat='pal'")==1,"Upgrade reindexes old combined references without original ZIP reimport");check(count(repo,"SELECT COUNT(*) FROM messages")==4,"Reindex preserves original message rows");repo.close();
  Activity media=startActivitySync(new Intent(c,MediaActivity.class).putExtra("chat","pal").putExtra("chat_title","Public fixture pal").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int i=0;i<200;i++){waitForIdleSync();if(!(Boolean)field(media,"loading")&&!(Boolean)field(media,"cataloging"))break;SystemClock.sleep(100);}List<?> items=(List<?>)field(media,"items");check(items.size()==1,"Chat-specific gallery renders exactly the linked public fixture asset");check(((String)field(items.get(0),"name")).equals("2024-01-02_b~abc.jpg"),"Gallery does not include unrelated dated media");runOnMainSync(media::finish);
 }
}
